import json, pathlib, statistics, html
root=pathlib.Path(__file__).resolve().parent
main_id='bake-1793872882228'
control_id=__import__('sys').argv[1]
arch_id='bake-1793870351281'
def read(capture):
    return json.loads((root/capture/'aether-archipelago.json').read_text())
def brief(capture):
    d=read(capture); out=[]
    for config in dict.fromkeys(r['config'] for r in d['rows']):
        for view in ['all','horizon','turn','near']:
            rows=[r for r in d['rows'] if r['config']==config and (view=='all' or r['view']==view)]
            frames=[f for r in rows for f in r['raw']];gpu=[g['spanMs'] for r in rows for g in r['gpu']]
            avg=lambda key:statistics.mean(f[key] for f in frames)
            out.append(dict(config=config,view=view,blocks=len(rows),frames=len(frames),fps=1000/avg('frame'),cpuMs=avg('cpu'),gpuMs=statistics.mean(gpu),
                frameMs=avg('frame'),drawCalls=avg('calls'),triangles=avg('triangles'),
                farDraws=statistics.mean(r['arena']['draws'] for r in rows),residentFaces=rows[0]['arena']['residentFaces'],
                arenaMiB=rows[0]['arena']['bytes']/2**20,textureMiB=rows[0]['texture'].get('bytes',0)/2**20))
    return out
main=read(main_id); control=read(control_id); arch=read(arch_id)
for name,data,count in [(main_id,main,18),(control_id,control,18),(arch_id,arch,24)]:
    assert len(data['rows'])==count and not data['errors']
    if (root/name/'failure.txt').exists(): assert name==main_id and (root/name/'failure.txt').read_text()=='Error: Capture failed: 400'
    assert all(r['pendingFrames']==0 for r in data['rows'])
assert (root/control_id/'complete.json').exists()
assert all(not r['settings']['textureProxyEnabled'] and not r['unified'] and r['pageFaces']==262144 and not r['texture'].get('used',0) for r in control['rows'])
M,C,A=map(brief,[main_id,control_id,arch_id])
control_base=next(r['fps'] for r in C if r['view']=='all' and r['config']=='off')
spread=max(abs(100*(r['fps']/control_base-1)) for r in C if r['view']=='all')
images=json.loads((root/main_id/'summary.json').read_text())['worlds'][0]['images']
control_images=json.loads((root/control_id/'summary.json').read_text())['worlds'][0]['images']
assert all(r['maxRgb']==0 for r in images if r['config']=='off')
assert all(r['maxRgb']<=1 for r in control_images)
selection=dict(date='2026-11-05',scope='Aether only; native Firefox 159 / WebGPU',framebuffer=[2560,1440],
    decision=dict(textureProxyEnabled=False,textureProxyEdge=32,textureProxyDensity=1,textureProxyDistance=384,textureProxyBudgetMiB=32,textureProxyLinear=False,textureProxyLodBias=0,textureProxyBatching=1),
    reason='Keep baking opt-in. Balanced preserves source topology; Maximum reduces draw calls further but does not establish a consistent frame-rate advantage. Extra geometry coarsening visibly changes island silhouettes and holes.',
    captureMarkerNote='All 18 final blocks and images saved. Writing the additional completion marker returned HTTP 400 because the receiver did not allow complete.json. The original failure.txt is retained; the receiver was fixed before the control run.',
    accepted=[dict(directory=arch_id,kind='architecture and coarse geometry comparison; earlier shader'),dict(directory=main_id,kind='final shader and production settings'),dict(directory=control_id,kind='identical-code order control; every label actually Off')],
    excluded=[dict(directory=p.name,reason='diagnostic probe, interrupted or superseded; excluded from final FPS conclusions') for p in sorted(root.glob('bake-*')) if p.name not in [main_id,control_id,arch_id]],
    results=dict(final=M,control=C,architecture=A),controlMaxAbsolutePooledLabelDifferencePercent=spread,
    validation=dict(relatedTests=121,englishCheck='Only existing native-space documentation/tests fail; no new violations.',balancedMaximumPixelExact=True,reportLinks='verified',engineTypecheck='passed',clientTypecheck='passed',productionBuild='passed',diffWhitespace='passed',webgpuErrors=0,pendingTerrainFrames=0,baselineRestoredPixelExact=True,controlImagesMaxRgbDelta=max(r['maxRgb'] for r in control_images),graphicsUiSwitching='verified in Firefox; restored Off / Balanced',interruptedBlocks=main.get('interruptedBlocks',0)),
    totals=dict(blocks=sum(len(d['rows']) for d in [main,control,arch]),frames=sum(len(r['raw']) for d in [main,control,arch] for r in d['rows']),gpuSamples=sum(len(r['gpu']) for d in [main,control,arch] for r in d['rows'])),
    limitations=['One machine; medium lighting, shadows off, 120 Hz presentation ceiling. No other terrain tested in this stage.', 'Settled horizon, turning and downward views. Loading, baking, uploads, transitions and image capture excluded from FPS.', 'Any backgrounded measurement block is discarded and retried after a 30-second foreground warmup.', 'Control label spread measures observed order/session effects, not a statistical confidence interval.', 'Baseline arena allocation depends on publication order: final-run Off draws ranged from 21 to 48. This is an additional batching/ordering confound beyond identical-code control spread.', 'Resident faces, submitted triangles and whole-frame draw calls are different measurements.', 'Baked colors use level-zero sampling with replicated chart borders; no mip chain. Coarse proxies cannot recover silhouette or occluded geometry with color textures.'])
(root/'selection.json').write_text(json.dumps(selection,ensure_ascii=False,indent=2)+'\n')
names={'off':'Baking Off','batch1024':'Large pages only','surface32':'Balanced: preserve shape + texture','unified32':'Maximum: unified texture shader','proxy32':'One extra geometry LOD + texture'}
views={'horizon':'Horizon','turn':'Turning','near':'Downward','all':'All views'}
def table(data):
    rows=''
    for r in data:
        if r['view']=='all':continue
        rows+=f"<tr><td>{names.get(r['config'],r['config'])}</td><td>{views[r['view']]}</td><td>{r['fps']:.1f}</td><td>{r['gpuMs']:.2f}</td><td>{r['farDraws']:.0f}</td><td>{r['drawCalls']:.0f}</td><td>{r['triangles']/1e6:.3f}</td></tr>"
    return '<div class="scroll"><table><thead><tr><th>Configuration</th><th>View</th><th>FPS</th><th>GPU ms</th><th>Far draws</th><th>Frame draws</th><th>Frame triangles / M</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
def img(capture,config,view):
    r=next(r for r in read(capture)['rows'] if r['config']==config and r['view']==view)
    return f"{capture}/aether-archipelago-{config}-{view}-{r['block']+1}.png"
def compare(capture,config,label):
    before=img(capture,'off','horizon');after=img(capture,config,'horizon')
    return f'<section><h3>{label}</h3><div class="comparison"><img src="{before}" alt="Baking Off"><img class="overlay" src="{after}" alt="{label}" style="clip-path:inset(0 0 0 50%)"></div><input class="reveal" aria-label="Compare baseline and candidate" type="range" value="50" min="0" max="100"><p class="muted">Left: baseline. Right: candidate. Drag the slider or open the <a href="{before}">baseline image</a> / <a href="{after}">candidate image</a>.</p></section>'
metrics=''.join(f'<li>{names[r["config"]]}: {r["fps"]:.1f} FPS, GPU {r["gpuMs"]:.2f} ms</li>' for r in M if r['view']=='all')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Aether distant proxy experiment - 2026-11-05</title><style>
:root{color-scheme:dark;font:16px/1.65 system-ui;background:#101720;color:#e5edf5}body{max-width:1160px;margin:0 auto;padding:40px 24px 80px}h1{font-size:32px;line-height:1.25}h2{margin-top:44px}h3{font-size:18px}p{max-width:950px}.muted{color:#9eafc0;font-size:14px}a{color:#84cbff}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#1b2835;padding:22px;border-radius:12px}.value{font-size:29px;color:#91dfbd;display:block}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px;white-space:nowrap}td,th{padding:11px;text-align:right;border-bottom:1px solid #304151}td:first-child,th:first-child{text-align:left}th{background:#1b2835}tr:nth-child(even){background:#15212d}.comparison{position:relative;aspect-ratio:16/9}.comparison img{position:absolute;width:100%;height:100%;object-fit:contain}.reveal{width:100%}li{margin:.4em 0}code{background:#223344;padding:2px 5px}@media(max-width:700px){.cards{grid-template-columns:1fr}body{padding:20px}}
</style><body><p class="muted">2026-11-05 · Aether only · Firefox 159 · WebGPU · 2560 × 1440</p><h1>Fewer faces and draws; no consistent FPS win</h1><p>Baking remains Off by default. Its opt-in preset uses 32 m surfaces, the original geometry LOD, one texel per source cell, a 384 m start distance, a 32 MiB texture pool, Sharp filtering and Balanced batching. Graphics settings offer Memory Saver / Balanced / Maximum batching and 0–2 additional geometry LOD levels.</p><div class="cards"><div class="card"><span class="value">−24.1%</span>Resident far faces<br>2,089,207 → 1,585,805</div><div class="card"><span class="value">16 draws</span>Maximum batching<br>Preserves neighboring tile order</div><div class="card"><span class="value">1,250 regions</span>Within a 32 MiB pool<br>122 array layers, zero capacity misses</div></div><h2>Final implementation</h2><p>Baselines bracket reversed candidate order. Each view warms up for 1.5 seconds and samples for 6 seconds. FPS is total frames divided by total elapsed frame time. GPU spans use timestamp-query. Horizon, turning and downward views cover different visible terrain.</p>'''+table(M)+'<ul>'+metrics+'</ul>'+f'<p>The identical-code control executes Baking Off under every configuration label. Its maximum pooled label difference was <strong>{spread:.2f}%</strong>. This is observed order/session variation, not a confidence interval or a correction to subtract.</p>'+'<details><summary>Identical-code control</summary>'+table(C)+'</details>'+'''<h2>Default decision and costs</h2><p>Maximum batching reduces draw calls substantially, but ordinary faces also pass through the texture-capable shader. It does not establish a consistent whole-frame advantage and loses FPS in the downward view. Balanced allocates about 54 MiB of arena buffers plus 32 MiB of textures; Maximum uses about 36 + 32 MiB. The baseline arena uses 40.5 MiB. Fewer resident faces do not imply lower total GPU memory or proportional frame-time savings.</p><p>Small immutable atlas regions share array layers. Updates upload only changed rectangles. The shader calculates atlas coordinates only for textured faces, combines coordinates and layer into one varying, and decodes descriptors directly from packed bytes. Repacking settled geometry pages did not reduce page or draw counts, so a runtime compactor was not added.</p><p>Page allocation depends on publication order. Final-run Off draws ranged from 21 to 48 across the bracketing baselines; Balanced ranged from 29 to 35; Maximum remained at 16. This allocation/order effect is an additional confound beyond identical-code timing spread. Do not compare only against the most favorable baseline.</p><h2>Image quality and extra coarsening</h2><p>The shape-preserving mode retains flat-space occupancy, holes and emission partitions. Large surfaces still interpolate differently under ring projection, so it is not pixel-exact. Pixels with maximum RGB channel change above 2/255 occupy approximately 0.88% of the horizon image and 0.66% of the downward image. One extra geometry LOD reduces resident faces by about 30.8%, but changes approximately 11% of pixels and visibly alters island silhouettes and openings. Extra coarsening defaults to 0; level 2 is exposed experimentally and was not selected by the browser study.</p>'''+compare(main_id,'surface32','Shape-preserving texture proxy')+compare(arch_id,'proxy32','One extra geometry LOD - rejected as the default')+'<details><summary>Earlier geometry and batching experiment (earlier shader)</summary>'+table(A)+'</details>'+'''<h2>Validation and scope</h2><p>121 relevant tests passed, as did engine/client type checks and the production build. Accepted timed blocks contain no WebGPU errors or pending terrain work. The final run restores pixel-exact baseline images. Identical-code control images differ by at most 1/255 in one channel; no pixel exceeds 2/255. Any backgrounded timed block is discarded and retried after a 30-second foreground warmup.</p><p>One machine, medium lighting, shadows off. Loading, baking, uploads, transitions and screenshots are excluded from steady-state FPS. Results do not establish benefits on mobile, other GPUs or other terrain. Color atlases use level-zero sampling with replicated chart borders and no mip chain. Color textures cannot restore missing silhouettes or occluded geometry.</p><p class="muted">All 18 final measurement blocks and images were saved. Writing the extra completion marker returned HTTP 400 because the local receiver did not allow that filename. The original failure.txt is retained for audit. The receiver was fixed, and the subsequent control run verified successful completion-marker saving.</p><h2>Reproducible data</h2><ul>'''+''.join(f'<li><a href="{c}/aether-archipelago.json">{label} · {c}</a> · <a href="{c}/summary.json">Summary and image differences</a></li>' for c,label in [(main_id,'Final implementation'),(control_id,'Identical-code control'),(arch_id,'Architecture comparison')])+'</ul><p><a href="selection.json">Settings decision, validation and excluded captures</a></p><script>document.querySelectorAll(".reveal").forEach(input=>input.oninput=()=>input.previousElementSibling.querySelector(".overlay").style.clipPath=`inset(0 0 0 ${input.value}%)`)</script></body></html>'
(root/'report.html').write_text(page)
print(json.dumps({'final':[r for r in M if r['view']=='all'],'controlSpread':spread,'totals':selection['totals']},ensure_ascii=False,indent=2))
